-- REQ-008/004/011/012: synthetic hosted SQL smoke, no permanent users or records.
-- Run through an authorized operator. Entire fixture and assertions roll back.
begin;
set local statement_timeout='60s';
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.expect_error(statement text,expected text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=expected then return; end if; raise exception 'FAIL: % expected %, received %',label,expected,sqlstate; end; raise exception 'FAIL: % unexpectedly allowed',label; end $$;
create temporary table cbc_smoke(role text,id uuid default gen_random_uuid(),organization_id uuid default gen_random_uuid(),contact_id uuid default gen_random_uuid(),program_id uuid default gen_random_uuid(),cohort_id uuid default gen_random_uuid(),contribution_id uuid default gen_random_uuid(),receipt_id uuid default gen_random_uuid());
insert into cbc_smoke(role) values('admin'),('staff'),('finance'),('viewer'),('inactive');
grant select on cbc_smoke to authenticated,anon;
insert into auth.users(id,email,raw_user_meta_data) select id,'verification.'||id::text||'@example.test',jsonb_build_object('full_name',case role when 'admin' then 'Morgan Hayes' when 'staff' then 'Jordan Ellis' when 'finance' then 'Evelyn Brooks' when 'viewer' then 'Noah Bennett' else 'Harper Reed' end) from cbc_smoke;
update public.profiles p set role=case when f.role='inactive' then 'staff'::public.app_role else f.role::public.app_role end,is_active=f.role<>'inactive' from cbc_smoke f where p.id=f.id;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select id::text from cbc_smoke where role='admin'),true);
select pg_temp.assert_true(public.current_role()='admin','admin role lookup');
select pg_temp.assert_true((select count(*)=5 from public.profiles where id in(select id from cbc_smoke)),'admin profile access');
insert into public.organizations(id,name,relationship_owner) select organization_id,'Juniper Harbour Partners',(select id from cbc_smoke where role='staff') from cbc_smoke where role='admin';
insert into public.organizations(id,name) select organization_id,'Alder Grove Learning' from cbc_smoke where role='staff';
insert into public.contacts(id,organization_id,first_name,last_name) select contact_id,organization_id,'Aisha','Morgan' from cbc_smoke where role='admin';
insert into public.contacts(id,organization_id,first_name,last_name) select contact_id,organization_id,'Daniel','Mensah' from cbc_smoke where role='staff';
insert into public.programs(id,name) select program_id,'Pathways Leadership Program' from cbc_smoke where role='admin';
insert into public.program_cohorts(id,program_id,label,year) select cohort_id,program_id,'Autumn Leaders Circle',2026 from cbc_smoke where role='admin';
insert into public.documents(name,access_level) values('Board Planning Brief','Admin only'),('Community Partnership Guide','Internal');
select pg_temp.expect_error($q$insert into public.mentorship_pairs(organization_id,mentor_id,mentee_id,program_id,cohort_id,start_date,status) select organization_id,contact_id,(select contact_id from cbc_smoke where role='staff'),program_id,cohort_id,public.activity_today(),'Active' from cbc_smoke where role='admin'$q$,'23503','same-organization mentorship constraint remains');
select pg_temp.expect_error($q$update public.profiles set role='viewer' where id in(select id from cbc_smoke)$q$,'42501','browser profile role writes denied');
select set_config('request.jwt.claim.sub',(select id::text from cbc_smoke where role='staff'),true);
select pg_temp.assert_true(public.current_role()='staff','staff role lookup');
select pg_temp.assert_true((select count(*)=1 from public.profiles where id in(select id from cbc_smoke)),'staff profiles restricted to self');
select pg_temp.assert_true((select count(*)=1 from public.staff_directory where id in(select id from cbc_smoke)),'restricted staff directory');
select pg_temp.expect_error($q$update public.organizations set relationship_owner=null where id=(select organization_id from cbc_smoke where role='admin')$q$,'42501','staff cannot reassign organization owner');
update public.organizations set notes='Prepare the partnership review' where id=(select organization_id from cbc_smoke where role='admin');
select pg_temp.expect_error($q$insert into public.contributions(contribution_date,amount,contribution_type) values(public.activity_today(),100,'Cash')$q$,'42501','staff financial insert denied');
select pg_temp.assert_true((select count(*)=0 from public.documents where name='Board Planning Brief'),'staff cannot read admin-only document');
select set_config('request.jwt.claim.sub',(select id::text from cbc_smoke where role='finance'),true);
select pg_temp.assert_true(public.current_role()='finance','finance role lookup');
select pg_temp.assert_true((select count(*)=0 from public.staff_directory),'finance staff directory denied');
insert into public.contributions(id,organization_id,contribution_date,amount,contribution_type,funding_status) select contribution_id,organization_id,public.activity_today(),100,'Cash','Committed' from cbc_smoke where role='admin';
insert into public.cash_receipts(id,contribution_id,received_on,amount) select receipt_id,contribution_id,public.activity_today(),40 from cbc_smoke where role='admin';
select pg_temp.assert_true((select cash_received::numeric=40 and outstanding::numeric=60 from public.contribution_details where id=(select contribution_id from cbc_smoke where role='admin')),'pledged versus partial received cash reconciles');
select pg_temp.assert_true((public.giving_summary(extract(year from public.activity_today())::int,(select organization_id from cbc_smoke where role='admin'),null)->>'annual_cash')::numeric=40,'scoped financial summary cash');
update public.cash_receipts set is_void=true,void_reason='Duplicate entry corrected during verification' where id=(select receipt_id from cbc_smoke where role='admin');
select pg_temp.assert_true((select cash_received::numeric=0 and outstanding::numeric=100 from public.contribution_details where id=(select contribution_id from cbc_smoke where role='admin')),'void correction preserves pledge without cash');
with changed as(update public.organizations set notes='Denied finance edit' where id=(select organization_id from cbc_smoke where role='admin') returning id) select pg_temp.assert_true((select count(*)=0 from changed),'finance CRM write denied');
select pg_temp.assert_true((select count(*)=0 from public.documents where name='Board Planning Brief'),'finance admin-only document denied');
select set_config('request.jwt.claim.sub',(select id::text from cbc_smoke where role='viewer'),true);
select pg_temp.assert_true(public.current_role()='viewer','viewer role lookup');
select pg_temp.assert_true((select count(*)=2 from public.organization_directory where id in(select organization_id from cbc_smoke)),'viewer directory reads through invoker view');
with changed as(update public.contributions set amount=1 where id=(select contribution_id from cbc_smoke where role='admin') returning id) select pg_temp.assert_true((select count(*)=0 from changed),'viewer financial update denied');
select pg_temp.expect_error($q$insert into public.organizations(name) values('Willow Vale Collective')$q$,'42501','viewer CRM insert denied');
select set_config('request.jwt.claim.sub',(select id::text from cbc_smoke where role='inactive'),true);
select pg_temp.assert_true(public.current_role() is null,'inactive role unavailable');
select pg_temp.assert_true((select count(*)=0 from public.organization_directory),'inactive directory denied');
select pg_temp.assert_true((select count(*)=0 from public.programs),'inactive programs denied');
reset role;
set local role anon;
select pg_temp.expect_error($q$select * from public.organizations$q$,'42501','anonymous table denied');
select pg_temp.expect_error($q$select public.current_role()$q$,'42501','anonymous role RPC denied');
select pg_temp.expect_error($q$select public.activity_today()$q$,'42501','anonymous activity RPC denied');
select pg_temp.expect_error($q$select public.handle_new_user()$q$,'42501','anonymous definer trigger RPC denied');
reset role;
rollback;
select 'PASS: hosted synthetic permission/financial/affiliation smoke; all fixtures rolled back' as result;
